CREATE TABLE `inspectionCases` (
	`id` text PRIMARY KEY NOT NULL,
	`clientId` text NOT NULL,
	`taxType` text NOT NULL,
	`periodKey` text NOT NULL,
	`staffId` text,
	`reviewerId` text,
	`approverId` text,
	`updateStaffId` text,
	`taskId` text,
	`sourceKey` text,
	`data` text NOT NULL,
	`revision` integer DEFAULT 1 NOT NULL,
	`created` text NOT NULL,
	`updated` text NOT NULL,
	FOREIGN KEY (`clientId`) REFERENCES `clients`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`staffId`) REFERENCES `staff`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`reviewerId`) REFERENCES `staff`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`approverId`) REFERENCES `staff`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`updateStaffId`) REFERENCES `staff`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`taskId`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE INDEX `idx_inspection_client` ON `inspectionCases` (`clientId`);--> statement-breakpoint
CREATE INDEX `idx_inspection_staff` ON `inspectionCases` (`staffId`);--> statement-breakpoint
CREATE UNIQUE INDEX `idx_inspection_period` ON `inspectionCases` (`clientId`,`taxType`,`periodKey`);--> statement-breakpoint
CREATE UNIQUE INDEX `idx_inspection_source` ON `inspectionCases` (`sourceKey`);--> statement-breakpoint
CREATE TABLE `inspectionHistory` (
	`id` text PRIMARY KEY NOT NULL,
	`caseId` text NOT NULL,
	`revision` integer NOT NULL,
	`data` text NOT NULL,
	`actor` text NOT NULL,
	`created` text NOT NULL,
	FOREIGN KEY (`caseId`) REFERENCES `inspectionCases`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE UNIQUE INDEX `idx_inspection_history` ON `inspectionHistory` (`caseId`,`revision`);
--> statement-breakpoint
